SELECT DISTINCT m.sector, m.db_name AS nome_no_banco
FROM missing m
WHERE NOT EXISTS (
  SELECT 1 FROM professionals p
  WHERE norm_name(p.full_name) = norm_name(m.db_name)
    AND p.active = true
);
